export var TemplateLoader={loadComponentSync:function(e,t){try{var o="http://localhost:58123/"+e,n=new XMLHttpRequest;if(n.open("GET",o,!1),n.send(null),200===n.status){var r=document.getElementById(t);r?r.innerHTML=n.responseText:console.error("Container with ID "+t+" not found.")}else console.error("Failed to load "+o+": "+n.status+" "+n.statusText)}catch(e){console.error("TemplateLoader error: "+e.message)}},appendComponentSync:function(e,t){try{var o="http://localhost:58123/"+e,n=new XMLHttpRequest;if(n.open("GET",o,!1),n.send(null),200===n.status){var r=document.getElementById(t);r?r.innerHTML+=n.responseText:console.error("Container with ID "+t+" not found.")}else console.error("Failed to load "+o+": "+n.status+" "+n.statusText)}catch(e){console.error("TemplateLoader error: "+e.message)}}};